import React, { useState } from 'react';
import { useAuth } from '/AuthContext';
import { useNavigate, Link } from 'react-router-dom';
import { doc, setDoc } from 'firebase/firestore';
import { db } from '../firebase/config';
// Importăm noul fișier CSS
import './RegistrationPage.css';

const RegistrationPage = () => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [role, setRole] = useState('adopter');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const { register } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        if (password.length < 6) {
            setError('Parola trebuie să aibă cel puțin 6 caractere.');
            setLoading(false);
            return;
        }

        try {
            // 1. Creăm userul în Authentication
            const userCredential = await register(email, password);
            const user = userCredential.user;

            // 2. Salvăm rolul în Firestore
            await setDoc(doc(db, "users", user.uid), {
                email: user.email,
                role: role,
                createdAt: new Date()
            });

            console.log("Înregistrare reușită! Rol:", role);
            // Redirecționarea se va face automat din App.js pe baza rolului
        } catch (err) {
            console.error("Eroare la înregistrare:", err.message);
            setError('Nu am putut crea contul. Verifică datele sau încearcă mai târziu.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="register-container">
            {/* Partea stângă - Imaginea */}
            <div className="register-image-section">
                <div className="image-text-content">
                    <h2>Alătură-te comunității PetPal</h2>
                    <p>Găsește-ți noul cel mai bun prieten sau ajută un animal să-și găsească o casă iubitoare.</p>
                </div>
            </div>

            {/* Partea dreaptă - Formularul */}
            <div className="register-form-section">
                <div className="register-card">
                    <h1 className="register-title">Creează Cont</h1>
                    <p className="register-subtitle">Completează detaliile pentru a începe.</p>

                    {error && <div className="error-message">{error}</div>}

                    <form onSubmit={handleSubmit}>
                        <div className="form-group">
                            <label htmlFor="email">Adresă de Email</label>
                            <input
                                id="email"
                                type="email"
                                placeholder="exemplu@email.com"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                                className="modern-input"
                            />
                        </div>

                        <div className="form-group">
                            <label htmlFor="password">Parolă</label>
                            <input
                                id="password"
                                type={showPassword ? "text" : "password"}
                                placeholder="Minimum 6 caractere"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                                className="modern-input"
                            />
                            <label className="password-toggle">
                                <input
                                    type="checkbox"
                                    checked={showPassword}
                                    onChange={() => setShowPassword(!showPassword)}
                                />
                                Afișează parola
                            </label>
                        </div>

                        <div className="form-group">
                            <label htmlFor="role">Vreau să...</label>
                            <select
                                id="role"
                                value={role}
                                onChange={(e) => setRole(e.target.value)}
                                className="modern-select"
                            >
                                <option value="adopter">Adopt un animal</option>
                                <option value="shelter">Înregistrez un adăpost (Shelter)</option>
                            </select>
                        </div>

                        <button type="submit" className="submit-btn" disabled={loading}>
                            {loading ? 'Se creează contul...' : 'Înregistrează-te'}
                        </button>
                    </form>

                    <p className="login-link">
                        Ai deja cont? <Link to="/login" className="link-text">Loghează-te aici</Link>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default RegistrationPage;
